-- cleanup-old-rows.sql — PREPARED ONLY, NOT EXECUTED (Step 9e, final).
-- Soft-deletes the 1697 old rows (CreatedAt < 2026-10-11 08:31:39.000,
-- i.e. everything before Run 1) that the FIXED BankingKeywordFilter
-- (Step 9b + 9d: Arabic word-boundary matching, tanwin-alef suffix,
-- negative phrases, banker/bankers) classifies as would-REMOVE.
-- Supersedes the Step 9b version (1697 ids): the USD rate-hike row has
-- been swapped out (now correctly KEEP) and the UK Biobank row swapped in
-- (now correctly REMOVE) — both already applied directly via
-- flips-9e-apply.sql. This script documents the FINAL state as of Step 9e
-- and is idempotent against it. A full backup
-- (data.NewsArticles_bak_20261011) already exists from Step 8.
--
-- Idempotent: safe to run more than once — the final UPDATE only touches
-- rows that are still IsDeleted = 0, so a second run affects 0 rows.
-- As of Step 9e, all 1697 ids are ALREADY soft-deleted, so running
-- this script now is expected to affect 0 rows (see WouldAffect below).

IF OBJECT_ID('tempdb..#CleanupIds') IS NOT NULL DROP TABLE #CleanupIds;
CREATE TABLE #CleanupIds (Id UNIQUEIDENTIFIER PRIMARY KEY);





-- Informational: how many rows this run will actually touch (excludes any
-- already soft-deleted by a prior run of this same script).
SELECT COUNT(*) AS WouldAffect
FROM data.NewsArticles a
JOIN #CleanupIds c ON c.Id = a.Id
WHERE a.IsDeleted = 0;

UPDATE a
SET a.IsDeleted = 1, a.UpdatedAt = SYSUTCDATETIME()
FROM data.NewsArticles a
JOIN #CleanupIds c ON c.Id = a.Id
WHERE a.IsDeleted = 0;

DROP TABLE #CleanupIds;
